    const name = String(r.name).trim().toUpperCase();
    const toName = `${toKey}${name.slice(fromKey.length)}`;
    const t = await c.execute({ sql: "SELECT id FROM ledger_accounts WHERE UPPER(TRIM(name)) = ?", args: [toName] });
