      from_id: n38(r.id),
      from_name: name,
      to_name: toName,
      to_id: t.rows.length ? n38(t.rows[0].id) : null,
      group: r.acc_group ?? null,
      lines: n38(r.lines),
      dr: n38(r.dr),
