        await c.execute({ sql: "UPDATE journal_lines SET account_id = ? WHERE account_id = ?", args: [l.to_id, l.from_id] });
        await c.execute({ sql: "UPDATE ledger_map SET use_name = ? WHERE TRIM(UPPER(use_name)) = ?", args: [l.to_name, l.from_name] });
